const char *hud_name_lookup(int iid) {
    if (iid < 0 || iid >= HUD_NAME_MAX) return 0;
    return hud_name[iid];
}

int hud_name_ids(int *out, int max) {
    int n = 0;
    for (int i = 2; i < HUD_NAME_MAX; i += 2) {
        if (!hud_name[i]) continue;
        if (out && n < max) out[n] = i;
        n++;
    }
    return n;
}
